import { useCallback, useState } from 'react';
import WorkHeroSky from '../components/WorkHeroSky';
import ProjectCard from '../components/ProjectCard';
import SocialIcons from '../components/SocialIcons';
import { projects } from '../data/projects';
import './WorkPage.css';

export default function WorkPage() {
  const [heroHoverCount, setHeroHoverCount] = useState(0);
  const heroHovered = heroHoverCount > 0;

  const setHeroActive = useCallback(() => {
    setHeroHoverCount((count) => count + 1);
  }, []);

  const setHeroInactive = useCallback(() => {
    setHeroHoverCount((count) => Math.max(0, count - 1));
  }, []);

  return (
    <div className="work-page">
      <div
        className="work-page__sky-hover"
        onMouseEnter={setHeroActive}
        onMouseLeave={setHeroInactive}
        aria-hidden="true"
      />

      <div className="work-page__sky" aria-hidden="true">
        <WorkHeroSky
          active={heroHovered}
          onHoverStart={setHeroActive}
          onHoverEnd={setHeroInactive}
        />
      </div>

      <div className="work-page__content">
        <section
          className="work-hero"
          onMouseEnter={setHeroActive}
          onMouseLeave={setHeroInactive}
        >
          <div className="work-hero__text">
            <h1 className="work-hero__title">DHIKSHIKA CHERIVIRALA</h1>
            <p className="work-hero__subtitle">
              Designing, developing, and delivering solutions that make an impact.
            </p>
            <p className="work-hero__bio">
              A CS student @ Cornell exploring the intersection of software
              engineering, product design, and social impact. ✦
            </p>
            <SocialIcons />
          </div>
        </section>

        <section className="work-grid" aria-label="Projects">
          {projects.map((project) => (
            <ProjectCard key={project.slug} project={project} />
          ))}
        </section>
      </div>
    </div>
  );
}
